import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;

public class ReportServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Custom filter - attempts to block obvious attacks but is bypassable
    private String sanitizeInput(String input) {
        if (input == null) return null;
        // Remove common SQL comment sequences
        input = input.replaceAll("/\\*.*?\\*/", "");
        // Remove double dashes
        input = input.replaceAll("--", "");
        return input;
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String department = req.getParameter("dept");
        String quarter = req.getParameter("quarter");
        String sortCol = req.getParameter("sort");

        if (department == null || quarter == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        department = sanitizeInput(department);
        quarter = sanitizeInput(quarter);

        // Validate quarter format loosely
        if (!quarter.matches("Q[1-4]_20[0-9]{2}")) {
            resp.sendError(400, "Invalid quarter format");
            return;
        }

        String orderClause = "";
        if (sortCol != null) {
            // Developer assumed sort column is safe since it's just a column name
            // but no validation is performed on this parameter
            orderClause = " ORDER BY " + sortCol;
        }

        String query = "SELECT employee_id, name, revenue, target " +
                       "FROM quarterly_reports " +
                       "WHERE department = '" + department + "' " +
                       "AND quarter = '" + quarter + "'" + orderClause;

        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append("  {");
                json.append("\"employee_id\": ").append(rs.getInt("employee_id")).append(", ");
                json.append("\"name\": \"").append(rs.getString("name")).append("\", ");
                json.append("\"revenue\": ").append(rs.getDouble("revenue")).append(", ");
                json.append("\"target\": ").append(rs.getDouble("target"));
                json.append("}");
                first = false;
            }
            json.append("\n]");
            out.print(json.toString());

        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // POST not supported for reports
        resp.sendError(405, "Method not allowed");
    }
}
